export const HEXADECIMAL_REGEXP=/^0x[a-fA-F0-9]+$/;export const DECIMAL_REGEXP=/^0$|[1-9]\d*$/;export function toHexString(t){const e=t.number.toString(16).padStart(t.pad,"0").toUpperCase();return t.prefix?"0x"+e:e}export function formatAddress(t){return toHexString({number:t,pad:8,prefix:!0})}export function parseAddress(t){const e=t.match(HEXADECIMAL_REGEXP),r=t.match(DECIMAL_REGEXP);let n;return e&&e[0].length===t.length?n=parseInt(t,16):r&&r[0].length===t.length&&(n=parseInt(t,10)),n}